edits.after:
if (*cow_len == 0) {
	/*
	 * We should find a refcounted record in the
	 * first pass.
	 */
	if (!(rec->e_flags & OCFS2_EXT_REFCOUNTED)) {
		ret = ocfs2_error(inode->i_sb,
				  "Inode %lu: extent at cpos %u is not refcounted but assumed to be\n",
				  inode->i_ino, cpos);
		goto out;
	}
	*cow_start = le32_to_cpu(rec->e_cpos);
}

